-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Marktmechanismen > Nachfrage
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Beeinflusst der Preis von Software die Nachfrage nach IT-Dienstleistungen eines IT-Betriebs?', 2, '[{"text": "Ja", "correct": true, "because": "Preis ist ein zentraler Faktor der Nachfrage"}, {"text": "Nein", "correct": false, "because": "Preis beeinflusst die Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Steigt die Nachfrage nach IT-Support, wenn die Qualität der Dienstleistung zunimmt?', 2, '[{"text": "Ja", "correct": true, "because": "Höhere Qualität kann die Nachfrage erhöhen"}, {"text": "Nein", "correct": false, "because": "Qualität ist ein Nachfragefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Nachfrage nach IT-Produkten durch Werbung beeinflusst werden?', 2, '[{"text": "Ja", "correct": true, "because": "Werbung kann die Nachfrage steigern"}, {"text": "Nein", "correct": false, "because": "Werbung ist ein Einflussfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Nachfrage nach IT-Dienstleistungen unabhängig vom Einkommen der Kunden?', 2, '[{"text": "Nein", "correct": true, "because": "Einkommen beeinflusst die Kaufkraft und Nachfrage"}, {"text": "Ja", "correct": false, "because": "Einkommen ist ein Nachfragefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sinkt die Nachfrage nach Software, wenn der Preis steigt?', 2, '[{"text": "Ja", "correct": true, "because": "Nachfrage sinkt meist bei Preiserhöhung (Nachfragegesetz)"}, {"text": "Nein", "correct": false, "because": "Preis und Nachfrage stehen in Beziehung"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was beschreibt die Nachfrage nach IT-Dienstleistungen eines IT-Betriebs am besten?', 2, '[{"text": "Bereitschaft der Kunden, Dienstleistungen zu kaufen", "correct": true, "because": "Nachfrage ist die Kaufwilligkeit"}, {"text": "Angebot der Dienstleistungen", "correct": false, "because": "Das ist Angebot"}, {"text": "Produktionskosten", "correct": false, "because": "Nicht relevant für Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Nachfrage nach Software eines IT-Betriebs am stärksten?', 3, '[{"text": "Preis der Software", "correct": true, "because": "Preis ist ein primärer Nachfragefaktor"}, {"text": "Farbe der Verpackung", "correct": false, "because": "Weniger relevant"}, {"text": "Größe des Betriebs", "correct": false, "because": "Indirekter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert mit der Nachfrage nach IT-Support, wenn das Einkommen der Kunden steigt?', 3, '[{"text": "Sie steigt", "correct": true, "because": "Höheres Einkommen erhöht die Kaufkraft"}, {"text": "Sie sinkt", "correct": false, "because": "Nachfrage steigt meist mit Einkommen"}, {"text": "Sie bleibt gleich", "correct": false, "because": "Einkommen beeinflusst die Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz beschreibt die Beziehung zwischen Preis und Nachfrage für IT-Produkte?', 2, '[{"text": "Nachfragegesetz", "correct": true, "because": "Preis und Nachfrage stehen in umgekehrter Beziehung"}, {"text": "Angebotsgesetz", "correct": false, "because": "Bezieht sich auf Angebot"}, {"text": "Kostengesetz", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Qualität bei der Nachfrage nach IT-Dienstleistungen?', 3, '[{"text": "Sie erhöht die Nachfrage", "correct": true, "because": "Höhere Qualität steigert die Nachfrage"}, {"text": "Sie senkt die Nachfrage", "correct": false, "because": "Qualität wirkt positiv"}, {"text": "Sie hat keinen Einfluss", "correct": false, "because": "Qualität beeinflusst die Nachfrage"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Nachfrage nach IT-Dienstleistungen eines IT-Betriebs?', 4, '[{"text": "Preis der Dienstleistung", "correct": true, "because": "Preis ist ein Haupteinflussfaktor"}, {"text": "Einkommen der Kunden", "correct": true, "because": "Einkommen bestimmt die Kaufkraft"}, {"text": "Wetterbedingungen", "correct": false, "because": "Weniger relevant"}, {"text": "Qualität der Dienstleistung", "correct": true, "because": "Qualität beeinflusst die Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen haben Preissenkungen auf die Nachfrage nach Software eines IT-Betriebs?', 3, '[{"text": "Die Nachfrage steigt", "correct": true, "because": "Nachfragegesetz: Preis sinkt, Nachfrage steigt"}, {"text": "Mehr Kunden kaufen", "correct": true, "because": "Günstigere Preise ziehen Kunden an"}, {"text": "Die Nachfrage sinkt", "correct": false, "because": "Umgekehrter Effekt"}, {"text": "Die Nachfrage bleibt gleich", "correct": false, "because": "Preisänderung wirkt sich aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente können die Nachfrage nach IT-Support eines IT-Betriebs steigern?', 4, '[{"text": "Preissenkung", "correct": true, "because": "Günstigere Preise erhöhen Nachfrage"}, {"text": "Bessere Qualität", "correct": true, "because": "Qualität steigert Nachfrage"}, {"text": "Werbekampagnen", "correct": true, "because": "Werbung erhöht Bekanntheit"}, {"text": "Höhere Produktionskosten", "correct": false, "because": "Kosten beeinflussen Angebot, nicht Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren könnten die Nachfrage nach IT-Produkten eines IT-Betriebs senken?', 3, '[{"text": "Preiserhöhung", "correct": true, "because": "Höhere Preise senken Nachfrage"}, {"text": "Sinkendes Einkommen der Kunden", "correct": true, "because": "Weniger Kaufkraft"}, {"text": "Bessere Werbung", "correct": false, "because": "Werbung steigert Nachfrage"}, {"text": "Schlechtere Qualität", "correct": true, "because": "Mindere Qualität senkt Nachfrage"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Nachfrage nach IT-Dienstleistungen von der Nachfrage nach IT-Produkten?', 3, '[{"text": "Dienstleistungen sind immateriell", "correct": true, "because": "Dienstleistungen sind nicht greifbar"}, {"text": "Produkte sind physisch", "correct": true, "because": "Produkte sind materiell"}, {"text": "Keine Preisunterschiede", "correct": false, "because": "Preise können variieren"}, {"text": "Dienstleistungen haben oft höhere Qualitätsanforderungen", "correct": true, "because": "Qualität ist bei Dienstleistungen entscheidend"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Nachfrage nach Software sinkt bei Preiserhöhung. b) Qualität hat keinen Einfluss auf die Nachfrage.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preiserhöhung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Einkommen der Kunden beeinflusst die Nachfrage nach IT-Dienstleistungen. b) Werbung kann die Nachfrage steigern.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Einkommen und Werbung beeinflussen Nachfrage"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Preissenkung erhöht die Nachfrage nach IT-Support. b) Nachfrage ist unabhängig vom Preis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preissenkung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Nachfrage nach IT-Produkten steigt bei besserer Qualität. b) Einkommen hat keinen Einfluss auf die Nachfrage.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Nachfragegesetz gilt für IT-Dienstleistungen. b) Nachfrage steigt bei schlechterer Qualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nachfragegesetz ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

